-- Rollback: UPDATE roadmap_implementation SET status = (SELECT b.status FROM bak_20261105_bs_defpub_row b WHERE b.id = roadmap_implementation.id), evidence = (SELECT b.evidence FROM bak_20261105_bs_defpub_row b WHERE b.id = roadmap_implementation.id), verified_at = (SELECT b.verified_at FROM bak_20261105_bs_defpub_row b WHERE b.id = roadmap_implementation.id) WHERE id IN (SELECT id FROM bak_20261105_bs_defpub_row); UPDATE agent_issues SET status = 'closed' WHERE source = 'session:w2-k-3271' AND title LIKE 'ROADMAP-1: QNFO.RSCH REGISTER-%';
