CREATE TABLE IF NOT EXISTS bak_20261105_bs_defpub_row AS SELECT id, item, source, status, evidence, verified_at FROM roadmap_implementation WHERE id = 3271;

UPDATE roadmap_implementation SET status = 'partial', verified_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
 evidence = 'PR 7668 merged 2026-11-05T04:03:30Z (qnfo-ipatent 3.21.0, REGISTER-1). Read live 2026-11-05 04:05-04:15Z: GET https://ipatent.qnfo.org/health reports version 3.21.0 with the capability defensive-register; GET /register answers 200 HTML with the title Open register of defensive publications, the canonical https://ipatent.qnfo.org/register, the not-legal-advice and not-a-patent labels and the text Nothing has been published yet; GET /register/publish answers 200 with Nothing is published until you tick the box, the consent checkbox not pre-ticked (<input type="checkbox" id="pc">), the publish button disabled and noindex; GET /register/withdraw answers 200; GET /api/register answers {"count":0,"consent_version":"dp-consent-1","items":[]}; /sitemap.xml lists /register; /llms.txt names it; GET /register/dp-zzzzzzzzzz is 404; POST /api/register/publish with consent false answers 400 (explicit consent required) and with a foreign Origin 403; scripts/deploy_probes.py --live qnfo-ipatent: ok for /health and /register/publish. Built: a consented register (never-pre-ticked consent whose exact text, version and time are stored with the record; only the disclosure text is published, never the print version or the inventor e-mail; a per-record page with og tags, a cite-as line and a SHA-256 fingerprint anyone can recompute; /api/register; withdrawal by code or private link that blanks the text; admin takedown; 30 a day cap; same-site POSTs only). 73 offline checks in qnfo-ipatent/register.test.mjs; phone journey scripts/ux-journeys/apps/ipatent.journeys.mjs (register-open-publish, 1 tap, 0 typing) merged and runs in ux-journeys.yml after deploys (playwright is not installed on the authoring machine, so it was not run here). Partial: no record has been published yet, no DOI, and the publisher is verified only by possession of the private link. Next slices: agent_issues REGISTER-2 and REGISTER-3 (session:w2-k-3271).'
WHERE id = 3271 AND item = 'RM-BS-DEFENSIVE-PUBLICATION-1' AND status = 'planned';

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'ROADMAP-1: QNFO.RSCH REGISTER-2: the defensive-publication register verifies its publisher only by the private link and mints no DOI',
 'QNFO.RSCH; charter pillar research; doer: qnfo-ipatent via qnfo-code-orchestrator; roadmap row 3271 RM-BS-DEFENSIVE-PUBLICATION-1. Built 2026-11-05 (PR 7668, qnfo-ipatent 3.21.0): https://ipatent.qnfo.org/register publishes a saved draft''s disclosure text after a recorded consent, with a SHA-256 fingerprint, a cite-as line and a withdrawal path. Two gaps remain. (1) Whoever holds a draft''s private link can publish it, which cannot be told from the inventor: where the draft stored an inventor e-mail address, hold a new publication as pending until that address confirms through a link to a page with one button (a POST confirms, because mail scanners fetch every link; the qnfo-subscribers confirm pattern), sent through the qnfo-email service binding with props.caller; a draft with no stored address keeps today''s flow and says so on its record. (2) The row promises DOIs: add a second, separate consent (never pre-ticked) to mint a DOI for a public record, stating that a DOI is permanent and survives withdrawal of the text, and hand the record to the fleet''s existing Zenodo publisher in qnfo-research-exec through a service binding (no Zenodo token in this worker); store the DOI in a new column, show it on the record page and in /api/register as "doi" (null until minted). Decision taken now, with its revert: the deposit names the depositor as the iPatent register at QNFO and the author only if the person typed a name to show; if Zenodo''s terms or the owner''s policy rule out depositing a third party''s text, replace the DOI step by an OpenTimestamps proof of the fingerprint with no third-party account. Carry the tag REGISTER-2 in a comment at the edit. Done: the runtime probe passes and tests cover a stored-address publication held pending, a confirmation, a DOI refused without the second consent and a withdrawn record refusing a DOI.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-ipatent/worker.js' || char(10) ||
 'code-anchor: async function handleRegPublish(request, env) {' || char(10) ||
 'runtime-probe: {"url":"https://ipatent.qnfo.org/api/register","status":200,"contains":"\"doi\""}' || char(10) ||
 'code-probe: {"paths":["qnfo-ipatent/worker.js"],"contains":"REGISTER-2"}',
 'session:w2-k-3271', 'code', 'medium', 'open', unixepoch() * 1000, unixepoch() * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'ROADMAP-1: QNFO.RSCH REGISTER-2:%' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'ROADMAP-1: QNFO.REACH REGISTER-3: iPatent has no guide on defensive publication and no worked example of a published record (PROD-29)',
 'QNFO.REACH; charter pillar reach; doer: qnfo-ipatent via qnfo-code-orchestrator; roadmap row 3271 RM-BS-DEFENSIVE-PUBLICATION-1 and scout idea PROD-29 (docs/BLUE-SKY-ROADMAP-2026-11.md, section 4). Measured 2026-11-05: https://ipatent.qnfo.org/guide/defensive-publication answers 404; the four guides cover provisionals, claims, drawings and filing, none says what a defensive publication is, when it helps and when it hurts. Work in qnfo-ipatent: add a GUIDE_PAGES entry with the slug defensive-publication (what it is; the United States one-year grace period against absolute novelty in Europe and most other countries, with each statement cited to its primary source, USPTO and EPO; what the register does and does not give: no filing date, no examination, a server clock and not a notary; when to file a provisional instead; how to publish and how to withdraw) and a second entry for the query provisional patent disclosure template, each with the existing not-legal-advice line and its date; link both from /register, the sitemap and llms.txt; add a worked example that links the first consented record once one exists and says so plainly until then. The text states only what its cited sources say; the PR records the author''s review as pending, because the author signs what carries the byline. Carry the tag REGISTER-3 in a comment at the edit. Done: the runtime probe passes and routes.test.mjs covers the new pages (200, canonical, only the author''s ORCID).' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-ipatent/worker.js' || char(10) ||
 'code-anchor: function renderGuidePage(page) {' || char(10) ||
