 'code-probe: {"paths":["qnfo-ipatent/worker.js"],"contains":"REGISTER-3"}',
 'session:w2-k-3271', 'code', 'low', 'open', unixepoch() * 1000, unixepoch() * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'ROADMAP-1: QNFO.REACH REGISTER-3:%' AND status = 'open');
